// Fleet brand icon: Vercel Unleashed's assigned product mark — the
// Break-Out ring with the Sky (#5FA8FF) shard (docs/UNLEASHED-BRAND-SPEC.md
// §3, §7: a product's app logo, favicon and connector icon all use its own
// accent file). Derivatives at 256 px and 64 px generated from the repo's
// master render, docs/unleashed-vercel.png. Base64 PNGs so one function
// can serve them with no static folder. (AUD-BW: this replaces the company
// R placeholder the pre-spec front door carried.)
export const ICON_256_PNG_BASE64 = '';
export const ICON_64_PNG_BASE64 = '';
export const iconBytes = (size) => Buffer.from(size === 64 ? ICON_64_PNG_BASE64 : ICON_256_PNG_BASE64, 'base64');
